        dict(name="幂等", signal="操作有外部副作用（扣费、发消息、建资源），且调用方会重试或消息会重投", solves="重试 / 重投导致副作用执行两次", how="调用方生成幂等键；执行方先查 completed[key]，再用 inflight[key] 保证同一时刻只有一个执行者；成功才缓存结果，失败不缓存", cost="要存幂等记录并设 TTL；跨系统的副作用需要下游也支持幂等键，否则只能对账", blocks=["p6"]),
        dict(name="限流", signal="共享的稀缺资源（模型配额、下游 QPS、GPU）被多个租户 / 实例争用", solves="一个租户打满资源导致别人全失败；超过上游配额被大面积 429", how="令牌桶按租户 + 资源分桶；多实例共享时把桶放 Redis 用 Lua 原子扣减；超限时排队或快速失败要按场景选", cost="集中式桶多一次网络往返、Redis 成为依赖；本地桶便宜但总量会被实例数放大", blocks=["p5"]),
        dict(name="恢复（checkpoint / 事件日志）", signal="任务耗时长（分钟到小时），中途进程重启、发布、机器故障是常态", solves="重启后从头再来、浪费算力、已执行的副作用被重做", how="把每一步的意图和结果追加写入持久化事件日志；恢复时重放日志重建状态，对“意图已写、结果未写”的步骤去下游对账", cost="写放大和存储成本；日志 schema 要向前兼容；重放要求逻辑确定性", blocks=["p9", "p3"]),
        dict(name="去重与顺序", signal="消息可能重复、乱序到达（多分区、重试、多路径）", solves="同一事件处理两次、后到的旧事件覆盖新状态", how="每个事件带单调序号（或版本号）；按 key 缓存乱序事件，只交付连续的下一个；重复序号直接丢弃", cost="缓冲区会涨，需要上限和超时补拉；全局有序代价高，通常只做到按 key 有序", blocks=["p7"]),
