        dict(name="事务与一致性（outbox / saga / 对账）", signal="一次业务动作要同时改本地状态和外部系统，不能只成功一半", solves="本地写成功但消息没发出（或反过来），两边状态不一致", how="本地事务里同时写业务数据和 outbox 记录，再异步投递；跨服务长流程用 saga 补偿；最后用定时对账兜底", cost="最终一致而非强一致；补偿逻辑要可重入；对账要有修复手段", blocks=["p6", "p9"]),
        dict(name="lease + fencing token", signal="多实例中只允许一个执行者（leader、session owner、任务 worker）", solves="进程卡住被判死后又活过来，两个执行者同时写（脑裂）", how="执行者定期续租；每次获得 lease 拿到单调递增的 token；所有写入带 token，存储层拒绝比已见 token 小的写", cost="续租依赖时钟和网络；lease 太短误判，太长故障切换慢", blocks=["p10", "p9"]),
